window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["bmw"]={html:"<div class=\"own-bmw\">\n  <header class=\"bw-nav\">\n    <a class=\"bw-badge\" href=\"#bw-top\" aria-label=\"Northwind home\">\n      <svg viewBox=\"0 0 48 48\" aria-hidden=\"true\"><circle cx=\"24\" cy=\"24\" r=\"21\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M24 3v42M3 24h42\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M24 24V3a21 21 0 0 1 0 42z\" fill=\"currentColor\" opacity=\".28\"/></svg>\n    </a>\n    <nav class=\"bw-menu\" aria-label=\"Primary\">\n      <a href=\"#bw-models\">Models</a>\n      <a href=\"#bw-grid\">Next generation</a>\n      <a href=\"#bw-inventory\">Pre-owned</a>\n      <a href=\"#bw-cta\">Dealers</a>\n      <a href=\"#bw-cta\">Test drive</a>\n    </nav>\n    <div class=\"bw-nav-right\">\n      <button class=\"bw-icobtn\" type=\"button\" aria-label=\"Search\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\"/><path d=\"m20 20-4-4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.7\" stroke-linecap=\"round\"/></svg></button>\n      <button class=\"bw-icobtn\" type=\"button\" aria-label=\"Wishlist\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 20s-7-4.4-7-9.2A3.8 3.8 0 0 1 12 8a3.8 3.8 0 0 1 7 2.8C19 15.6 12 20 12 20Z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg></button>\n      <button class=\"bw-icobtn\" type=\"button\" aria-label=\"Profile\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"9\" r=\"3.2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"M5 20c1.4-3.4 4-5 7-5s5.6 1.6 7 5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/></svg></button>\n    </div>\n  </header>\n\n  <main id=\"bw-top\">\n    <section class=\"bw-hero\" aria-labelledby=\"bw-h1\">\n      <div class=\"bw-hero-copy\">\n        <p class=\"bw-hero-label\">Northwind Operations</p>\n        <h1 id=\"bw-h1\" class=\"bw-hero-h\">The network,<br>engineered to read.</h1>\n        <p class=\"bw-hero-sub\">Every region on one governed model. Throughput, yield, and cost resolved to the same number — the way a factory floor deserves to be measured.</p>\n        <div class=\"bw-hero-cta\">\n          <a class=\"bw-btn bw-btn-primary\" href=\"#bw-grid\">Explore the boards</a>\n          <a class=\"bw-btn bw-btn-secondary-dark\" href=\"#bw-cta\">Book a walkthrough</a>\n        </div>\n      </div>\n      <div class=\"bw-hero-visual\" aria-hidden=\"true\">\n        <div class=\"bw-lines\">\n          <span style=\"height:44%\"></span><span style=\"height:60%\"></span><span style=\"height:52%\"></span><span style=\"height:74%\"></span><span style=\"height:66%\"></span><span style=\"height:88%\"></span><span style=\"height:80%\"></span><span style=\"height:96%\"></span>\n        </div>\n        <div class=\"bw-hero-chip\"><b>98.1%</b><span>on-time, all regions</span></div>\n      </div>\n    </section>\n\n    <section class=\"bw-mstripe\" aria-label=\"Northwind M performance\"></section>\n\n    <section id=\"bw-models\" class=\"bw-band\" aria-labelledby=\"bw-models-h\">\n      <div class=\"bw-band-head\">\n        <h2 id=\"bw-models-h\" class=\"bw-h2\">Choose your board</h2>\n        <a class=\"bw-textlink\" href=\"#\">View all boards <span aria-hidden=\"true\">›</span></a>\n      </div>\n      <div class=\"bw-model-grid\" id=\"bwModelGrid\"></div>\n    </section>\n\n    <section id=\"bw-grid\" class=\"bw-spec\" aria-labelledby=\"bw-spec-h\">\n      <h2 id=\"bw-spec-h\" class=\"bw-h2\">The numbers behind the board</h2>\n      <div class=\"bw-spec-row\">\n        <div class=\"bw-spec-cell\"><b>412k</b><span class=\"bw-spec-label\">Units / day</span></div>\n        <div class=\"bw-spec-cell\"><b>94.6%</b><span class=\"bw-spec-label\">Line yield</span></div>\n        <div class=\"bw-spec-cell\"><b>12</b><span class=\"bw-spec-label\">Regions live</span></div>\n        <div class=\"bw-spec-cell\"><b>$2.41</b><span class=\"bw-spec-label\">Cost / unit</span></div>\n        <div class=\"bw-spec-cell\"><b>99.98%</b><span class=\"bw-spec-label\">Model uptime</span></div>\n      </div>\n    </section>\n\n    <section id=\"bw-inventory\" class=\"bw-inventory\" aria-labelledby=\"bw-inv-h\">\n      <div class=\"bw-band-head\">\n        <h2 id=\"bw-inv-h\" class=\"bw-h2\">Region inventory</h2>\n        <div class=\"bw-filters\" id=\"bwFilters\" role=\"group\" aria-label=\"Filter regions\"></div>\n      </div>\n      <div class=\"bw-inv-list\" id=\"bwInvList\"></div>\n    </section>\n\n    <section class=\"bw-config\" aria-labelledby=\"bw-config-h\">\n      <div class=\"bw-config-copy\">\n        <p class=\"bw-config-label\">Configure your plan</p>\n        <h2 id=\"bw-config-h\" class=\"bw-h2\">Ops tier · up to 40 seats</h2>\n        <p class=\"bw-body\">Add regions at $180 per month. The first thirty days are free, no card required.</p>\n        <p class=\"bw-config-price\"><span id=\"bwAmount\">$4,900</span><small>/ month</small></p>\n        <a class=\"bw-btn bw-btn-primary\" href=\"#\">Request this plan</a>\n      </div>\n      <div class=\"bw-config-tiles\" id=\"bwConfigTiles\" role=\"radiogroup\" aria-label=\"Regions included\"></div>\n    </section>\n\n    <section id=\"bw-cta\" class=\"bw-cta\" aria-labelledby=\"bw-cta-h\">\n      <div class=\"bw-cta-copy\">\n        <h2 id=\"bw-cta-h\" class=\"bw-cta-h\">Book your operations walkthrough</h2>\n        <p class=\"bw-cta-sub\">Thirty minutes with the ops desk, on your own data.</p>\n      </div>\n      <a class=\"bw-btn bw-btn-secondary-dark\" href=\"#\">Find a dealer <span aria-hidden=\"true\">›</span></a>\n    </section>\n  </main>\n\n  <footer class=\"bw-footer\">\n    <div class=\"bw-foot-cols\">\n      <div class=\"bw-foot-col\"><h3>Models</h3><a href=\"#\">Throughput board</a><a href=\"#\">Yield board</a><a href=\"#\">Cost board</a><a href=\"#\">Compare</a></div>\n      <div class=\"bw-foot-col\"><h3>Services</h3><a href=\"#\">Ops desk</a><a href=\"#\">Onboarding</a><a href=\"#\">Support</a></div>\n      <div class=\"bw-foot-col\"><h3>Dealers</h3><a href=\"#\">Find a partner</a><a href=\"#\">Become a partner</a><a href=\"#\">Regional desks</a></div>\n      <div class=\"bw-foot-col\"><h3>About</h3><a href=\"#\">Company</a><a href=\"#\">Careers</a><a href=\"#\">Contact</a></div>\n    </div>\n    <div class=\"bw-legal\">\n      <span>© 2026 Northwind Analytics — sample data, showcase only.</span>\n      <span class=\"bw-legal-links\"><a href=\"#\">Legal notice</a><a href=\"#\">Privacy</a><a href=\"#\">Cookies</a></span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — in the BMW corporate design language, for showcase.html ════\n   Light canvas, dark navy hero bands, single BMW-blue CTA, BMW Type Next Latin\n   (Inter + system fallback) with the signature 700 display / 300 body contrast,\n   UPPERCASE letter-spaced links, rectangular 0px buttons, and the M tricolor\n   stripe reserved for an accent divider. */\n\n.own-bmw {\n  --primary: #1c69d4;\n  --primary-active: #0653b6;\n  --primary-disabled: #d6d6d6;\n  --ink: #262626;\n  --body: #3c3c3c;\n  --body-strong: #1a1a1a;\n  --muted: #6b6b6b;\n  --muted-soft: #9a9a9a;\n  --hairline: #e6e6e6;\n  --hairline-strong: #cccccc;\n  --canvas: #ffffff;\n  --surface-soft: #f7f7f7;\n  --surface-card: #fafafa;\n  --surface-strong: #ebebeb;\n  --surface-dark: #1a2129;\n  --surface-dark-elevated: #262e38;\n  --on-primary: #ffffff;\n  --on-dark: #ffffff;\n  --on-dark-soft: #bbbbbb;\n  --m-blue-light: #0066b1;\n  --m-blue-dark: #1c69d4;\n  --m-red: #e22718;\n  --font: 'BMW Type Next Latin', 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\n  --gut: clamp(20px, 4.5cqi, 72px);\n  --section: clamp(56px, 7cqi, 80px);\n\n  position: relative;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--font);\n  font-size: 16px;\n  line-height: 1.55;\n  text-align: left;\n  border-radius: 13px;\n  overflow-x: clip;\n}\n.own-bmw *, .own-bmw *::before, .own-bmw *::after { box-sizing: border-box; }\n.own-bmw a { color: inherit; text-decoration: none; }\n.own-bmw button { font: inherit; cursor: pointer; }\n.own-bmw :focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }\n\n/* ── buttons (rectangular 0px — the corporate signature) ──────────────────── */\n.own-bmw .bw-btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; height: 48px; padding: 0 32px; border: 1px solid transparent; border-radius: 0; font-size: 14px; font-weight: 700; letter-spacing: .5px; }\n.own-bmw .bw-btn-primary { background: var(--primary); color: var(--on-primary); }\n.own-bmw .bw-btn-primary:hover { background: var(--primary-active); }\n.own-bmw .bw-btn-secondary-dark { background: transparent; color: var(--on-dark); border-color: var(--on-dark); }\n.own-bmw .bw-btn-secondary-dark:hover { background: rgba(255, 255, 255, .1); }\n.own-bmw .bw-textlink { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--ink); }\n.own-bmw .bw-textlink:hover { color: var(--primary); }\n\n/* ── top nav (64px, white sticky) ─────────────────────────────────────────── */\n.own-bmw .bw-nav { position: sticky; top: 68px; z-index: 30; display: flex; align-items: center; gap: 24px; height: 64px; padding: 0 var(--gut); background: var(--canvas); border-bottom: 1px solid var(--hairline); }\n.own-bmw .bw-badge { display: grid; place-items: center; color: var(--ink); }\n.own-bmw .bw-badge svg { width: 40px; height: 40px; }\n.own-bmw .bw-menu { display: flex; gap: 26px; font-size: 14px; font-weight: 400; letter-spacing: .3px; }\n.own-bmw .bw-menu a:hover { color: var(--primary); }\n.own-bmw .bw-nav-right { display: flex; align-items: center; gap: 6px; margin-left: auto; }\n.own-bmw .bw-icobtn { display: grid; place-items: center; width: 40px; height: 40px; border: 0; border-radius: 50%; background: transparent; color: var(--ink); }\n.own-bmw .bw-icobtn:hover { background: var(--surface-strong); }\n.own-bmw .bw-icobtn svg { width: 20px; height: 20px; }\n\n/* ── hero (dark navy band) ────────────────────────────────────────────────── */\n.own-bmw .bw-hero { display: grid; grid-template-columns: 1.05fr .95fr; gap: 48px; align-items: center; max-width: 1440px; margin: 0 auto; padding: var(--section) var(--gut); background: var(--surface-dark); color: var(--on-dark); }\n.own-bmw .bw-hero-label { font-size: 13px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--on-dark-soft); margin-bottom: 14px; }\n.own-bmw .bw-hero-h { font-size: clamp(40px, 6.4cqi, 64px); font-weight: 700; line-height: 1.05; }\n.own-bmw .bw-hero-sub { font-size: 16px; font-weight: 300; line-height: 1.55; color: #d9dde2; max-width: 48ch; margin: 22px 0 30px; }\n.own-bmw .bw-hero-cta { display: flex; gap: 16px; flex-wrap: wrap; }\n.own-bmw .bw-hero-visual { position: relative; display: grid; gap: 20px; }\n.own-bmw .bw-lines { display: flex; align-items: flex-end; gap: 10px; height: 260px; padding: 26px; background: var(--surface-dark-elevated); }\n.own-bmw .bw-lines span { flex: 1; background: linear-gradient(180deg, #6f98d8, var(--primary)); }\n.own-bmw .bw-hero-chip { position: absolute; right: 0; bottom: -20px; display: grid; gap: 2px; padding: 18px 24px; background: var(--primary); color: #fff; }\n.own-bmw .bw-hero-chip b { font-size: 40px; font-weight: 700; line-height: 1; }\n.own-bmw .bw-hero-chip span { font-size: 12px; font-weight: 400; letter-spacing: .5px; }\n\n/* ── M tricolor stripe (accent divider only) ──────────────────────────────── */\n.own-bmw .bw-mstripe { height: 4px; background: linear-gradient(90deg, var(--m-blue-light) 0 33.33%, var(--m-blue-dark) 33.33% 66.66%, var(--m-red) 66.66% 100%); }\n\n/* ── band ─────────────────────────────────────────────────────────────────── */\n.own-bmw .bw-band { max-width: 1440px; margin: 0 auto; padding: var(--section) var(--gut); }\n.own-bmw .bw-band-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; flex-wrap: wrap; margin-bottom: 32px; }\n.own-bmw .bw-h2 { font-size: clamp(26px, 3.4cqi, 32px); font-weight: 700; line-height: 1.15; }\n.own-bmw .bw-body { font-size: 16px; font-weight: 300; color: var(--body); }\n\n/* ── model cards (4-up) ───────────────────────────────────────────────────── */\n.own-bmw .bw-model-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }\n.own-bmw .bw-model { display: grid; gap: 4px; padding: 24px; background: var(--canvas); border-bottom: 1px solid transparent; transition: border-color .15s; }\n.own-bmw .bw-model:hover { border-bottom-color: var(--primary); }\n.own-bmw .bw-model-photo { display: grid; place-items: end center; aspect-ratio: 16 / 10; margin-bottom: 16px; padding: 22px; background: var(--surface-card); overflow: hidden; }\n.own-bmw .bw-model-photo svg { width: 100%; height: 100%; }\n.own-bmw .bw-model-name { font-size: 18px; font-weight: 700; line-height: 1.4; }\n.own-bmw .bw-model-tag { font-size: 14px; font-weight: 300; color: var(--body); }\n.own-bmw .bw-model .bw-textlink { margin-top: 12px; color: var(--primary); }\n\n/* ── spec band ────────────────────────────────────────────────────────────── */\n.own-bmw .bw-spec { max-width: 1440px; margin: 0 auto; padding: 0 var(--gut) var(--section); }\n.own-bmw .bw-spec .bw-h2 { margin-bottom: 32px; }\n.own-bmw .bw-spec-row { display: grid; grid-template-columns: repeat(5, 1fr); border-top: 1px solid var(--hairline); }\n.own-bmw .bw-spec-cell { display: grid; gap: 6px; padding: 24px; border-right: 1px solid var(--hairline); }\n.own-bmw .bw-spec-cell:last-child { border-right: 0; }\n.own-bmw .bw-spec-cell b { font-size: 24px; font-weight: 700; line-height: 1.25; }\n.own-bmw .bw-spec-label { font-size: 13px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--muted); }\n\n/* ── inventory (filters + cards) ──────────────────────────────────────────── */\n.own-bmw .bw-inventory { max-width: 1440px; margin: 0 auto; padding: 0 var(--gut) var(--section); }\n.own-bmw .bw-filters { display: flex; gap: 0; flex-wrap: wrap; }\n.own-bmw .bw-chip { padding: 8px 14px; border: 1px solid var(--hairline-strong); background: var(--canvas); color: var(--ink); font-size: 12px; font-weight: 400; letter-spacing: .5px; }\n.own-bmw .bw-chip + .bw-chip { border-left: 0; }\n.own-bmw .bw-chip.on { background: var(--ink); color: var(--on-dark); border-color: var(--ink); }\n.own-bmw .bw-inv-list { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-bmw .bw-inv { display: grid; gap: 4px; padding: 16px; border: 1px solid var(--hairline); }\n.own-bmw .bw-inv-photo { display: grid; place-items: center; aspect-ratio: 16 / 10; margin-bottom: 12px; background: var(--surface-soft); }\n.own-bmw .bw-inv-photo svg { width: 70%; height: auto; }\n.own-bmw .bw-inv-name { font-size: 16px; font-weight: 700; }\n.own-bmw .bw-inv-meta { font-size: 14px; font-weight: 300; color: var(--muted); }\n.own-bmw .bw-inv-price { font-size: 16px; font-weight: 700; margin-top: 6px; }\n.own-bmw .bw-inv .bw-textlink { color: var(--primary); margin-top: 8px; }\n.own-bmw .bw-inv-empty { grid-column: 1 / -1; padding: 40px 0; font-size: 16px; font-weight: 300; color: var(--muted); }\n\n/* ── configurator ─────────────────────────────────────────────────────────── */\n.own-bmw .bw-config { display: grid; grid-template-columns: .8fr 1.2fr; gap: 48px; align-items: center; max-width: 1440px; margin: 0 auto; padding: 0 var(--gut) var(--section); }\n.own-bmw .bw-config-label { font-size: 13px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--primary); margin-bottom: 12px; }\n.own-bmw .bw-config .bw-h2 { margin-bottom: 12px; }\n.own-bmw .bw-config-price { font-size: 40px; font-weight: 700; line-height: 1.1; margin: 18px 0 22px; }\n.own-bmw .bw-config-price small { font-size: 16px; font-weight: 300; color: var(--muted); }\n.own-bmw .bw-config-tiles { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0; }\n.own-bmw .bw-tile { padding: 16px 24px; border: 1px solid var(--hairline); background: var(--canvas); text-align: left; }\n.own-bmw .bw-tile + .bw-tile { border-left: 0; }\n.own-bmw .bw-tile b { display: block; font-size: 16px; font-weight: 300; }\n.own-bmw .bw-tile span { font-size: 12px; letter-spacing: .5px; color: var(--muted); }\n.own-bmw .bw-tile[aria-checked=\"true\"] { border: 2px solid var(--primary); padding: 15px 23px; }\n.own-bmw .bw-tile[aria-checked=\"true\"] + .bw-tile { border-left: 1px solid var(--hairline); }\n\n/* ── dark CTA band ────────────────────────────────────────────────────────── */\n.own-bmw .bw-cta { display: flex; align-items: center; justify-content: space-between; gap: 32px; flex-wrap: wrap; max-width: 1440px; margin: 0 auto var(--section); padding: 80px var(--gut); background: var(--surface-dark); color: var(--on-dark); }\n.own-bmw .bw-cta-h { font-size: clamp(26px, 3.4cqi, 32px); font-weight: 700; line-height: 1.15; }\n.own-bmw .bw-cta-sub { font-size: 16px; font-weight: 300; color: var(--on-dark-soft); margin-top: 10px; }\n\n/* ── footer (soft grey) ───────────────────────────────────────────────────── */\n.own-bmw .bw-footer { background: var(--surface-soft); padding: 64px var(--gut) 32px; }\n.own-bmw .bw-foot-cols { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; max-width: 1440px; margin: 0 auto; }\n.own-bmw .bw-foot-col { display: grid; gap: 10px; align-content: start; }\n.own-bmw .bw-foot-col h3 { font-size: 16px; font-weight: 700; margin-bottom: 6px; }\n.own-bmw .bw-foot-col a { font-size: 14px; font-weight: 300; color: var(--body); }\n.own-bmw .bw-foot-col a:hover { color: var(--primary); }\n.own-bmw .bw-legal { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; max-width: 1440px; margin: 40px auto 0; padding-top: 20px; border-top: 1px solid var(--hairline-strong); font-size: 14px; font-weight: 300; color: var(--muted); }\n.own-bmw .bw-legal-links { display: inline-flex; gap: 18px; }\n.own-bmw .bw-legal-links a:hover { color: var(--primary); }\n\n/* ── responsive ───────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-bmw .bw-menu { display: none; }\n  .own-bmw .bw-hero { grid-template-columns: 1fr; gap: 40px; }\n  .own-bmw .bw-model-grid { grid-template-columns: repeat(2, 1fr); }\n  .own-bmw .bw-spec-row { grid-template-columns: repeat(2, 1fr); }\n  .own-bmw .bw-spec-cell:nth-child(2n) { border-right: 0; }\n  .own-bmw .bw-inv-list { grid-template-columns: repeat(2, 1fr); }\n  .own-bmw .bw-config { grid-template-columns: 1fr; gap: 32px; }\n  .own-bmw .bw-foot-cols { grid-template-columns: repeat(2, 1fr); }\n}\n@container frame (max-width: 760px) {\n  .own-bmw .bw-nav { top: 0; padding: 0 16px; gap: 12px; }\n  .own-bmw .bw-nav-right .bw-icobtn:nth-child(2) { display: none; }\n  .own-bmw .bw-hero { padding: 48px 16px; }\n  .own-bmw .bw-hero-h br { display: none; }\n  .own-bmw .bw-lines { height: 180px; }\n  .own-bmw .bw-band, .own-bmw .bw-spec, .own-bmw .bw-inventory, .own-bmw .bw-config { padding: 0 16px 48px; }\n  .own-bmw .bw-model-grid { grid-template-columns: 1fr; }\n  .own-bmw .bw-spec-row { grid-template-columns: 1fr; }\n  .own-bmw .bw-spec-cell { border-right: 0; border-bottom: 1px solid var(--hairline); }\n  .own-bmw .bw-inv-list { grid-template-columns: 1fr; }\n  .own-bmw .bw-config-tiles { grid-template-columns: 1fr; }\n  .own-bmw .bw-tile + .bw-tile { border-left: 1px solid var(--hairline); border-top: 0; }\n  .own-bmw .bw-cta { margin: 0 16px 48px; padding: 48px 16px; }\n  .own-bmw .bw-footer { padding: 48px 16px 24px; }\n}\n@container frame (max-width: 430px) {\n  .own-bmw .bw-foot-cols { grid-template-columns: 1fr; }\n}\n@media (prefers-reduced-motion: reduce) {\n  .own-bmw *, .own-bmw *::before, .own-bmw *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — BMW corporate-language operations site for showcase.html ══
   Registers window.OWN_LAYOUTS['bmw'].init(root). Renders the model cards and
   dealer inventory, wires filter chips and the configurator tiles, keeps the
   plan price in sync, and returns a cleanup that detaches every listener. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  var MODELS = [
    { name: 'Throughput board', tag: 'Live units per day, every line', seed: 1 },
    { name: 'Yield board', tag: 'Passing grade across all lines', seed: 2 },
    { name: 'Cost board', tag: 'Cost per unit, indexed by region', seed: 3 },
    { name: 'Fulfilment board', tag: 'First-touch and on-time, per hub', seed: 4 }
  ];
  var INVENTORY = [
    { name: 'Luzon', variant: 'Assembly cluster', price: '$412k/day', kind: 'live' },
    { name: 'Busan', variant: 'Port operations', price: '$287k/day', kind: 'live' },
    { name: 'Singapore', variant: 'Distribution centre', price: '$344k/day', kind: 'live' },
    { name: 'Visayas', variant: 'Logistics hub', price: '$198k/day', kind: 'planned' },
    { name: 'Mindanao', variant: 'Agri ops cluster', price: '$176k/day', kind: 'planned' },
    { name: 'Rotterdam', variant: 'Recycling lines', price: '$133k/day', kind: 'live' }
  ];
  var FILTERS = [['all', 'All'], ['live', 'Live'], ['planned', 'Planned']];
  var BASE = 4700, PER_REGION = 180, INCLUDED = 1;

  function esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); }
  function money(n) { return '$' + Number(n).toLocaleString('en-US'); }

  /* a simple abstract "vehicle"/region silhouette, built from divs + SVG */
  function silhouette(seed) {
    var bars = [38, 54, 46, 68, 60, 82].map(function (h, i) {
      return '<rect x="' + (10 + i * 24) + '" y="' + (74 - h) + '" width="14" height="' + h + '" rx="2" fill="#1c69d4" opacity="' + (0.45 + ((i + seed) % 3) * 0.2) + '"/>';
    }).join('');
    return '<svg viewBox="0 0 160 80" preserveAspectRatio="xMidYMid meet" aria-hidden="true">' + bars + '</svg>';
  }

  OWN['bmw'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      function on(el, type, fn, opt) { if (!el) return; opt = Object.assign({}, opt || {}); if (signal) opt.signal = signal; el.addEventListener(type, fn, opt); }
      function $(s) { return root.querySelector(s); }

      var models = $('#bwModelGrid');
      if (models) {
        models.innerHTML = MODELS.map(function (m) {
          return '<article class="bw-model">'
            + '<div class="bw-model-photo">' + silhouette(m.seed) + '</div>'
            + '<h3 class="bw-model-name">' + esc(m.name) + '</h3>'
            + '<p class="bw-model-tag">' + esc(m.tag) + '</p>'
            + '<a class="bw-textlink" href="#">Learn more <span aria-hidden="true">›</span></a>'
            + '</article>';
        }).join('');
      }

      var filters = $('#bwFilters');
      var filter = 'all';
      var invList = $('#bwInvList');
      function renderInv() {
        var list = INVENTORY.filter(function (v) { return filter === 'all' || v.kind === filter; });
        invList.innerHTML = list.length ? list.map(function (v) {
          return '<article class="bw-inv">'
            + '<div class="bw-inv-photo">' + silhouette(v.name.length) + '</div>'
            + '<h3 class="bw-inv-name">' + esc(v.name) + '</h3>'
            + '<p class="bw-inv-meta">' + esc(v.variant) + '</p>'
            + '<p class="bw-inv-price">' + esc(v.price) + '</p>'
            + '<a class="bw-textlink" href="#">View <span aria-hidden="true">›</span></a>'
            + '</article>';
        }).join('') : '<p class="bw-inv-empty">No regions match this filter.</p>';
      }
      if (filters) filters.innerHTML = FILTERS.map(function (f) {
        return '<button class="bw-chip' + (f[0] === filter ? ' on' : '') + '" type="button" data-f="' + f[0] + '" aria-pressed="' + (f[0] === filter) + '">' + f[1] + '</button>';
      }).join('');
      on(filters, 'click', function (e) {
        var c = e.target.closest('[data-f]'); if (!c) return;
        filter = c.dataset.f;
        Array.prototype.forEach.call(filters.children, function (x) { x.classList.toggle('on', x === c); x.setAttribute('aria-pressed', String(x === c)); });
        renderInv();
      });
      renderInv();

      var tiles = $('#bwConfigTiles');
      var regions = 3;
      var COUNT = [1, 3, 6, 12];
      function renderTiles() {
        tiles.innerHTML = COUNT.map(function (n) {
          return '<button class="bw-tile" type="button" role="radio" data-n="' + n + '" aria-checked="' + (n === regions) + '">'
            + '<b>' + n + ' region' + (n > 1 ? 's' : '') + '</b><span>' + (n === 1 ? 'included' : '+' + money((n - INCLUDED) * PER_REGION) + '/mo') + '</span></button>';
        }).join('');
        var amt = $('#bwAmount');
        if (amt) amt.textContent = money(BASE + Math.max(0, regions - INCLUDED) * PER_REGION);
      }
      on(tiles, 'click', function (e) {
        var t = e.target.closest('[data-n]'); if (!t) return;
        regions = Number(t.dataset.n); renderTiles();
      });
      renderTiles();

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
      };
    }
  };
})();
